import {getPreferences,setPreferences} from './preferences.js';
import {playSound,updateAudio} from './audio.js';
import {playAttackEffect} from './effects.js';

const ICONS={profile:'☺',display:'▣',performance:'ϟ',audio:'♫',account:'☁',help:'ⓘ'};
const TABS=[['profile','Profil','Titres, cadres et photo'],['display','Affichage','Thème et confort'],['performance','Performances','Fluidité et effets visuels'],['audio','Audio','Volume et sons d’attaque'],['account','Compte et sauvegarde','Connexion et progression'],['help','Aide et informations','Commandes du jeu']];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

export function mountSettings(container,{getName,onName,onPreferences,mountProfile}){
 let section='profile';
 container.innerHTML=`<div class="settings-shell"><nav class="settings-nav" role="tablist" aria-label="Rubriques des paramètres" aria-orientation="vertical">${TABS.map(([id,title,sub],i)=>`<button id="settings-tab-${id}" class="settings-tab" role="tab" aria-controls="settings-panel" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-settings-tab="${id}"><span class="settings-symbol" aria-hidden="true">${ICONS[id]}</span><span><strong>${title}</strong><small>${sub}</small></span><b aria-hidden="true">›</b></button>`).join('')}</nav><section class="settings-main" role="tabpanel" id="settings-panel" aria-labelledby="settings-tab-profile"></section></div><p class="settings-save-status" id="settings-save-status" role="status">Les réglages sont enregistrés automatiquement.</p>`;
 const root=container.querySelector('.settings-shell'),panel=container.querySelector('#settings-panel'),status=container.querySelector('#settings-save-status');
 const choices=(pref,items)=>`<div class="setting-choices" role="group" aria-label="${pref==='theme'?'Apparence':'Qualité graphique'}">${items.map(([value,label,sub])=>`<button type="button" class="setting-choice" data-preference="${pref}" data-value="${value}" aria-pressed="${getPreferences()[pref]===value}"><strong>${label}</strong><small>${sub}</small></button>`).join('')}</div>`;
 const toggle=(pref,title,sub)=>`<label class="setting-toggle"><span><strong>${title}</strong><small>${sub}</small></span><input type="checkbox" data-preference="${pref}" ${getPreferences()[pref]?'checked':''}><span class="switch-track" aria-hidden="true"></span></label>`;
 function show(){const p=getPreferences();const tab=TABS.find(t=>t[0]===section);panel.setAttribute('aria-labelledby','settings-tab-'+section);panel.innerHTML=`<header class="settings-section-title"><h3>${tab[1]}</h3><p>${tab[2]}</p></header><div class="settings-cards">`+({
  profile:'<div id="profile-host"></div>',
  display:`<article class="setting-card"><h4>Apparence</h4><p>Choisis l’ambiance de ton interface.</p>${choices('theme',[['dark','Nuit','Bleu océan'],['light','Jour','Clair et lumineux']])}<button type="button" class="setting-wide-button" data-settings-fullscreen>⛶ Passer en plein écran</button></article><article class="setting-card wide"><h4>Confort visuel</h4>${toggle('reducedMotion','Réduire les animations','Limite les déplacements, les secousses et les effets lumineux. Les sons restent réglables séparément.')}</article<article class="setting-card wide"><h4>Combat</h4>${toggle('skipLearn','Ne plus demander quelle attaque oublier','Quand un Pokémon apprend une attaque et connaît déjà 4 attaques, rien n’est demandé : il garde ses attaques actuelles. Tu peux les changer à tout moment depuis son profil.')}</article>`,
  performance:`<article class="setting-card wide"><h4>Qualité des effets</h4><p>Le réglage change les animations et les Pokémon du décor. Les chances de tirage restent identiques.</p>${choices('quality',[['eco','Économie','Décor fixe · effets désactivés'],['standard','Équilibré','5 Pokémon · 30 images/s'],['high','Élevée','Jusqu’à 10 Pokémon · 60 images/s']])}</article><article class="setting-card wide"><h4>Animations de combat</h4>${toggle('effects','Effets des attaques','Flammes, griffures et impacts courts. Désactivés en mode Économie ou si les animations sont réduites.')}<p class="setting-note">Les animations du décor se mettent en pause lorsque l’onglet est masqué.</p></article>`,
  audio:`<article class="setting-card"><h4>Effets sonores</h4>${toggle('sound','Activer les sons','Bruitage des attaques pendant les combats.')}<label class="setting-label volume-label" for="settings-volume">Volume <output id="settings-volume-value">${p.volume} %</output></label><input id="settings-volume" data-preference="volume" type="range" min="0" max="100" step="1" value="${p.volume}" aria-label="Volume des effets sonores"></article><article class="setting-card"><h4>Écouter les attaques</h4><p>Deux bruitages rétro recréés à partir des séquences Game Boy de Rouge et Bleu.</p><div class="sound-tests"><button type="button" data-sound-test="ember">🔥 Flammèche</button><button type="button" data-sound-test="scratch">〃 Griffe</button></div><div class="effect-preview" id="effect-preview" aria-label="Aperçu de l’animation d’attaque"><img src="https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/25.png" alt="Pikachu"></div><span id="sound-test-status" class="setting-footnote" role="status">Clique pour écouter et voir un aperçu.</span></article>`,
  account:`<article class="setting-card wide"><span class="account-pill">Mode invité</span><h4>Ton compte de dresseur</h4><p>La connexion Google et Discord sera activée lors de l’ajout du service de comptes en ligne.</p><div class="account-providers"><button type="button" disabled><span class="provider-logo google" aria-hidden="true">G</span><span>Continuer avec Google</span><small>À venir</small></button><button type="button" disabled><span class="provider-logo discord" aria-hidden="true">◉</span><span>Continuer avec Discord</span><small>À venir</small></button></div></article><article class="setting-card wide"><h4>Sauvegarde automatique</h4><div class="local-save-state"><span aria-hidden="true">●</span><strong>Progression conservée sur cet appareil</strong></div><p>Ton équipe, ta collection et ton expérience sont enregistrées dans ce navigateur. La synchronisation entre appareils arrivera avec les comptes en ligne. Effacer les données du navigateur supprime aussi cette progression.</p></article>`,
  help:`<article class="setting-card"><h4>Commandes</h4><dl class="settings-shortcuts"><div><dt>Tirage / fuite</dt><dd>Espace</dd></div><div><dt>Attaques en combat</dt><dd>1 à 4</dd></div><div><dt>Fermer un menu</dt><dd>Échap</dd></div></dl></article><article class="setting-card"><h4>Pokéluck</h4><p>151 espèces de Kanto, combats et progression de puissance. L’équilibrage reste provisoire.</p><p>Les sons de Griffe et Flammèche sont une synthèse rétro des séquences d’origine, pas des enregistrements des jeux.</p><a href="https://github.com/lucasfr6-tech/pokeluck-rng" target="_blank" rel="noreferrer">Ouvrir le dépôt GitHub ↗</a></article>`
 })[section]+'</div>';if(section==='profile'&&mountProfile)mountProfile(panel.querySelector('#profile-host'));}
 function update(pref,value){const result=setPreferences({[pref]:value});updateAudio();onPreferences(result.preferences);status.textContent=result.persisted?'Réglages enregistrés automatiquement.':'Réglages appliqués pour cette session ; le stockage du navigateur est indisponible.';root.querySelectorAll(`[data-preference="${pref}"][data-value]`).forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.value===value)));}
 root.addEventListener('click',async e=>{const tab=e.target.closest('[data-settings-tab]');if(tab){section=tab.dataset.settingsTab;root.querySelectorAll('[data-settings-tab]').forEach(b=>{const selected=b===tab;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;});show();return;}const choice=e.target.closest('[data-preference][data-value]');if(choice){update(choice.dataset.preference,choice.dataset.value);return;}const sound=e.target.closest('[data-sound-test]');if(sound){const p=getPreferences();const text=panel.querySelector('#sound-test-status');if(!p.sound||p.volume===0){text.textContent='Active les sons et augmente le volume pour écouter.';return;}const result=await playSound(sound.dataset.soundTest);playAttackEffect({moveKey:sound.dataset.soundTest,move:sound.dataset.soundTest,target:'wild',silent:true},panel.querySelector('#effect-preview'));text.textContent=result?'Aperçu : '+(sound.dataset.soundTest==='ember'?'Flammèche':'Griffe'):'Le navigateur ne permet pas de lire le son pour le moment.';return;}if(e.target.closest('[data-settings-fullscreen]')){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{status.textContent='Le plein écran n’est pas disponible dans cette fenêtre.';}}});
 root.addEventListener('change',e=>{const input=e.target;if(input.id==='trainer-setting-name'){const name=input.value.trim()||'Dresseur';input.value=name;onName(name);status.textContent='Pseudo enregistré automatiquement.';}else if(input.matches('input[type=checkbox][data-preference]'))update(input.dataset.preference,input.checked);});
 root.addEventListener('input',e=>{if(e.target.id==='settings-volume'){const value=+e.target.value;panel.querySelector('#settings-volume-value').textContent=value+' %';update('volume',value);}});
 root.querySelector('[role=tablist]').addEventListener('keydown',e=>{if(!['ArrowDown','ArrowUp','Home','End'].includes(e.key))return;e.preventDefault();const buttons=[...root.querySelectorAll('[data-settings-tab]')],i=buttons.indexOf(document.activeElement),next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length;buttons[next].focus();buttons[next].click();});
 show();
}
